#!/bin/sh
# Code generated by AI (Claude Code)
# read-source-state pre hook, runs on every chezmoi command so it must exit fast once done

set -e

# shellcheck disable=SC1091
. "$(dirname "$0")/log.sh"

# shellcheck disable=SC1091
. "$(dirname "$0")/sudo.sh"

# nix.conf only gets this setting from the first home-manager switch, which runs after this hook
export NIX_CONFIG="use-xdg-base-directories = true"

single="$HOME/.local/state/nix/profile/etc/profile.d/nix.sh"
multi=/nix/var/nix/profiles/default/etc/profile.d/nix-daemon.sh

# renovate: datasource=github-tags packageName=NixOS/nix
nix_version=2.36.0
nix_installer="https://releases.nixos.org/nix/nix-$nix_version/install"

# a pre-existing multi-user nix must not trigger the single-user installer
if [ ! -f "$single" ] && [ ! -f "$multi" ]; then
  # the single-user installer only calls sudo itself when /nix is missing
  if [ ! -d /nix ]; then
    if ! sudo_run mkdir /nix; then
      error "/nix can't be created, run as root: mkdir /nix && chown $USER /nix"
    fi
    if ! sudo_run chown "$USER" /nix; then
      error "/nix isn't owned by $USER, run as root: chown $USER /nix"
    fi
  fi

  if command -v curl >/dev/null 2>&1; then
    curl -fsSL "$nix_installer" | sh -s -- --no-channel-add --no-daemon --no-modify-profile
  elif command -v wget >/dev/null 2>&1; then
    wget -qO- "$nix_installer" | sh -s -- --no-channel-add --no-daemon --no-modify-profile
  else
    error "Neither curl nor wget is installed, one is needed to install nix"
  fi
fi

# shellcheck disable=SC1090
if [ -f "$single" ]; then . "$single"; else . "$multi"; fi

# the installer's channel step reads its certificates from ~/.nix-profile, which the XDG setting never creates
if [ -f "$single" ] && [ ! -e "$HOME/.local/state/nix/defexpr/channels/nixpkgs" ]; then
  nix-channel --add https://nixos.org/channels/nixpkgs-unstable nixpkgs
  nix-channel --update
fi

# tools the modify_ scripts need, a GC-rooted build independent from home.nix and its apply order
env="$HOME/.local/state/chezmoi/env"
if [ ! -x "$env/bin/python3" ]; then
  mkdir -p "$(dirname "$env")"
  nix-build -E 'with import <nixpkgs> {}; buildEnv { name = "chezmoi-env"; paths = [ jq (python3.withPackages (ps: [ ps.tomlkit ])) ]; }' -o "$env"
fi

# same delay as minimum_release_age in 10-settings.toml, and an installed mise is left to mise self-update
if [ ! -x "$HOME/.local/bin/mise" ]; then
  if command -v curl >/dev/null 2>&1; then
    curl -fsSL "https://mise.run" | MISE_INSTALL_PATH="$HOME/.local/bin/mise" MISE_MINIMUM_RELEASE_AGE=4d sh
  elif command -v wget >/dev/null 2>&1; then
    wget -qO- "https://mise.run" | MISE_INSTALL_PATH="$HOME/.local/bin/mise" MISE_MINIMUM_RELEASE_AGE=4d sh
  else
    error "Neither curl nor wget is installed, one is needed to install mise"
  fi
fi

# home-manager init keeps an existing home.nix, otherwise its default one is overwritten in the file phase
if ! command -v home-manager >/dev/null 2>&1; then
  nix-channel --add https://github.com/nix-community/home-manager/archive/master.tar.gz home-manager
  nix-channel --update
  nix-shell '<home-manager>' -A install
fi
